const statementLineCounts = `-- name: StatementLineCounts :many
SELECT status, count(*)::int AS n FROM finance.bank_statement_lines WHERE account_id = $1 GROUP BY status
`

type StatementLineCountsRow struct {
	Status string
	N      int32
}

func (q *Queries) StatementLineCounts(ctx context.Context, accountID string) ([]StatementLineCountsRow, error) {
	rows, err := q.db.Query(ctx, statementLineCounts, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StatementLineCountsRow{}
	for rows.Next() {
		var i StatementLineCountsRow
		if err := rows.Scan(&i.Status, &i.N); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

